/* ---------- Utilitários ---------- */
function monthKey(d){ return d.slice(0,7); }
function fmtMonthLabel(ym){
  const [y,m] = ym.split('-').map(Number);
  const names = ["Janeiro","Fevereiro","Março","Abril","Maio","Junho","Julho","Agosto","Setembro","Outubro","Novembro","Dezembro"];
  return `${names[m-1]}/${y}`;
}
function todayISO(){ return new Date().toISOString().slice(0,10); }
function uid(){ return Math.random().toString(36).slice(2,10); }

function toast(msg){
  let t = document.getElementById('toast');
  if(!t){
    t = document.createElement('div');
    t.id = 'toast';
    t.className = 'toast';
    document.body.appendChild(t);
  }
  t.textContent = msg;
  t.classList.add('show');
  clearTimeout(toast._h);
  toast._h = setTimeout(()=> t.classList.remove('show'), 2400);
}

function openModal(html){
  document.getElementById('modalBox').innerHTML = html;
  document.getElementById('modalBg').classList.add('active');
}
function closeModal(){
  document.getElementById('modalBg').classList.remove('active');
  document.getElementById('modalBox').innerHTML = '';
}

/* ---------- Autenticação / sessão ---------- */
// Toda página deve ter no <body>: <div id="sidebarMount"></div> <div id="modalBg" class="modal-bg"><div id="modalBox" class="modal-box"></div></div>
// e chamar guardStaff('home') ou guardAthlete('roteiros') logo no início do seu <script>.

async function getSessionUser(){
  const { data } = await sb.auth.getSession();
  return data?.session?.user || null;
}

async function loadProfile(userId){
  const { data } = await sb.from('profiles').select('*').eq('id', userId).single();
  return data ? {id:data.id, nome:data.nome, role:data.role} : {id:userId, nome:'', role:'geral'};
}

// Chame no topo de cada página da EQUIPE. Redireciona pro login se não tiver
// sessão, ou pro portal do atleta se quem logou for um atleta.
async function guardStaff(activeId){
  const user = await getSessionUser();
  if(!user){ location.href = 'login.html'; return null; }
  const profile = await loadProfile(user.id);
  if(profile.role === 'atleta'){ location.href = 'atleta-roteiros.html'; return null; }
  renderStaffSidebar(activeId, profile);
  return { user, profile };
}

// Chame no topo de cada página do ATLETA.
async function guardAthlete(activeId){
  const user = await getSessionUser();
  if(!user){ location.href = 'login.html'; return null; }
  const profile = await loadProfile(user.id);
  if(profile.role !== 'atleta'){ location.href = 'home.html'; return null; }
  const { data: athleteRow } = await sb.from('athletes').select('*').eq('auth_user_id', user.id).single();
  const athlete = athleteRow ? mapAthleteFromDB(athleteRow) : null;
  renderAthleteSidebar(activeId, athlete);
  return { user, profile, athlete };
}

async function logout(){
  await sb.auth.signOut();
  location.href = 'login.html';
}

/* ---------- Sidebar (mesmo HTML/CSS pros dois tipos de usuário) ---------- */
function sidebarShell(navHtml, footerHtml){
  return `
    <aside class="sidebar">
      <img src="${LOGO_SIMBOLO_BRANCO}" alt="FourLab" style="height:32px; width:auto; align-self:center; display:block; margin-bottom:4px;">
      <div class="brand-sub">Roteiros &amp; Atletas</div>
      <nav class="sidebar-nav">${navHtml}</nav>
      <div class="sidebar-footer">${footerHtml}</div>
    </aside>`;
}

function renderStaffSidebar(activeId, profile){
  const nav = STAFF_NAV.map(t=>
    `<a class="nav-btn ${activeId===t.id?'active':''}" href="${t.href}"><span class="ic">${t.ic}</span><span class="label">${t.label}</span></a>`
  ).join('');
  const footer = `${profile?.nome || 'Usuário'} · ${profile?.role === 'chefia' ? 'Chefia' : 'Geral'}
    <button onclick="logout()" style="display:flex; align-items:center; gap:5px; margin-top:6px; background:none; border:none; color:rgba(255,255,255,0.7); font-size:11px; cursor:pointer; text-decoration:underline; padding:0;">${ICONS.sair} Sair</button>`;
  document.getElementById('sidebarMount').innerHTML = sidebarShell(nav, footer);
}

function renderAthleteSidebar(activeId, athlete){
  const tabs = ATLETA_NAV.filter(t=> t.id !== 'vendas' || (athlete && athlete.cupomYampi));
  const nav = tabs.map(t=>
    `<a class="nav-btn ${activeId===t.id?'active':''}" href="${t.href}"><span class="ic">${t.ic}</span><span class="label">${t.label}</span></a>`
  ).join('');
  const footer = `${athlete ? athlete.name : 'Atleta'} · ${athlete ? athlete.team : ''}
    <button onclick="logout()" style="display:flex; align-items:center; gap:5px; margin-top:6px; background:none; border:none; color:rgba(255,255,255,0.7); font-size:11px; cursor:pointer; text-decoration:underline; padding:0;">${ICONS.sair} Sair</button>`;
  document.getElementById('sidebarMount').innerHTML = sidebarShell(nav, footer);
}

/* ---------- Mapeamento de atleta (usado em várias páginas) ---------- */
function mapAthleteFromDB(r){
  return {id:r.id, name:r.name, team:r.team, formatPref:r.format_pref, notes:r.notes||'',
    dificuldadeGravacao:r.dificuldade_gravacao||'', estiloFala:r.estilo_fala||'',
    estiloVideo:r.estilo_video||'', videosTranscritos:r.videos_transcritos||'',
    cupomYampi:r.cupom_yampi||'', descontoCupomPct:r.desconto_cupom_pct, comissaoPct:r.comissao_pct,
    username:r.username||'',
    email:r.email||'', whatsapp:r.whatsapp||'', instagram:r.instagram||'', facebook:r.facebook||'',
    tiktok:r.tiktok||'', youtube:r.youtube||'', pixKey:r.pix_key||'',
    enderecoCep:r.endereco_cep||'', enderecoRua:r.endereco_rua||'', enderecoNumero:r.endereco_numero||'',
    enderecoComplemento:r.endereco_complemento||'', enderecoBairro:r.endereco_bairro||'',
    enderecoCidade:r.endereco_cidade||'', enderecoEstado:r.endereco_estado||''};
}

document.addEventListener('click', (e)=>{
  if(e.target.id === 'modalBg') closeModal();
});
